import{_ as o}from"./chunks/Audio.COine8Wh.js";import{_ as t}from"./chunks/Tags.BJ536pW3.js";import{c as i,o as n,j as a,G as r,ae as s,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"VA Home Loan Program Reform Act","description":"","frontmatter":{"legisId":"2025-07-30-va-home-loan-program-reform-act","title":"VA Home Loan Program Reform Act","displayTitle":"VA Home Loan Program Reform Act","lawNumber":"119-31","billNumber":"H.R. 1815","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ31.xml","publishDate":"2025-07-30T00:00:00-05:00","industries":["housing","finance"],"agencies":["Department of Veterans Affairs"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"VA Home Loan Program Reform Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-30-va-home-loan-program-reform-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"VA Home Loan Program Reform Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-30-va-home-loan-program-reform-act\\",\\"datePublished\\":\\"2025-07-30T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-07-30-va-home-loan-program-reform-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-07-30-va-home-loan-program-reform-act.md","filePath":"congress-bills/2025-07-30-va-home-loan-program-reform-act.md","lastUpdated":1788887623000}'),m={name:"congress-bills/2025-07-30-va-home-loan-program-reform-act.md"},h=Object.assign(m,{setup(p){return(c,e)=>(n(),i("div",null,[e[0]||(e[0]=a("h1",{id:"va-home-loan-program-reform-act",tabindex:"-1"},[l("VA Home Loan Program Reform Act "),a("a",{class:"header-anchor",href:"#va-home-loan-program-reform-act","aria-label":'Permalink to "VA Home Loan Program Reform Act"'},"​")],-1)),r(o),r(t,{list:"/congress-bills"}),e[1]||(e[1]=s('<p>Signed into law on Wednesday, July 30, 2025. Public Law 119-31, H.R. 1815.</p><p><strong>Headline:</strong> The law expands VA foreclosure-prevention tools and support for veterans facing housing instability.</p><p><strong>Why it matters:</strong> Veterans with troubled VA-guaranteed mortgages gain a new way to address overdue debt and a required sequence of options before foreclosure.</p><p><strong>What the law does:</strong></p><ul><li>Creates a five-year Partial Claim Program allowing VA to cover overdue mortgage debt in exchange for a secondary lien on the home.</li><li>Requires loan holders to offer VA-ordered foreclosure-prevention options before VA may purchase or otherwise manage the full loan.</li><li>Limits a partial claim generally to 25 percent of unpaid principal, or 30 percent for certain borrowers who missed payments from March 1, 2020, through May 1, 2025.</li><li>Generally allows one partial claim per loan, with another possible after missed payments tied to a presidentially declared major disaster.</li><li>Requires a VA strategy to protect veterans’ access to real estate agents or brokers.</li><li>Authorizes $344 million annually for homeless-veteran programs in fiscal years 2025 and 2026, and $257.7 million annually through fiscal year 2030.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Veterans with VA-guaranteed primary-residence loans in default or at imminent risk of default.</li><li>Holders of VA-guaranteed loans that must follow VA’s foreclosure-prevention sequence.</li><li>Veterans using homeless-veteran services or seeking real estate representation.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>An eligible veteran may resolve part of overdue mortgage debt through a VA payment secured by a secondary lien.</li><li>A struggling borrower must be offered VA-prescribed alternatives before foreclosure or certain other loan actions proceed.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="va-home-loan-program-reform-act-1" tabindex="-1">VA Home Loan Program Reform Act <a class="header-anchor" href="#va-home-loan-program-reform-act-1" aria-label="Permalink to &quot;VA Home Loan Program Reform Act&quot;">​</a></h3><p>The law expands the Department of Veterans Affairs’ tools to help veterans avoid foreclosure on VA-guaranteed home loans. It creates a five-year Partial Claim Program that allows VA to cover part of a borrower’s overdue debt in exchange for a secondary lien on the home, and it requires loan holders to follow a VA-set sequence of foreclosure-prevention options. It also requires a strategy addressing veterans’ access to real estate representation and increases funding authorization for homeless-veteran service programs.</p><p><strong>Key takeaways:</strong></p><ul><li>VA may pay loan holders amounts needed to prevent foreclosure, require forbearance, and obtain a secured interest in the veteran’s property.</li><li>VA must establish an ordered sequence of loss-mitigation options that loan holders must offer veterans before VA may purchase the entire loan or use certain other loan-management powers.</li><li>The new Partial Claim Program applies to VA-guaranteed loans on primary residences that are in default or at imminent risk of default.</li><li>A partial claim generally may cover up to 25 percent of the unpaid principal balance, but the limit is 30 percent for certain borrowers who missed payments between March 1, 2020, and May 1, 2025.</li><li>Generally, only one partial claim is allowed per loan, although an additional claim may be available for missed payments during or within 120 days after a presidentially declared major disaster.</li><li>The law requires VA to report on protecting veterans’ access to real estate agents or brokers and authorizes $344 million annually for homeless-veteran programs in fiscal years 2025 and 2026 and $257.7 million annually through fiscal year 2030.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ31.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ31.xml</a></p>',15))]))}});export{u as __pageData,h as default};
